func ptrInvoiceAdjustmentControl(p unsafe.Pointer, c int32) any {
	r := (*invoiceadjustmentcontrol.InvoiceAdjustmentControl)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.PartiallyPaidInvoiceAdjustmentPolicy))
	case 4:
		return (*string)(unsafe.Pointer(&r.PaidInvoiceAdjustmentPolicy))
	case 5:
		return (*string)(unsafe.Pointer(&r.DisputedInvoiceAdjustmentPolicy))
	case 6:
		return (*string)(unsafe.Pointer(&r.AdjustmentAccountingDatePolicy))
	case 7:
		return (*string)(unsafe.Pointer(&r.ClosedPeriodAdjustmentPolicy))
	case 8:
		return (*string)(unsafe.Pointer(&r.AdjustmentReasonRequirement))
	case 9:
		return (*string)(unsafe.Pointer(&r.StandardAdjustmentApprovalPolicy))
	case 10:
		return &r.StandardAdjustmentApprovalThreshold
	case 11:
		return (*string)(unsafe.Pointer(&r.WriteOffApprovalPolicy))
	case 12:
		return &r.WriteOffApprovalThreshold
	case 13:
		return &r.RequireSeparateApprover
	case 14:
		return &r.RerateVarianceTolerancePercent
	case 15:
		return (*string)(unsafe.Pointer(&r.ReplacementInvoiceReviewPolicy))
	case 16:
		return (*string)(unsafe.Pointer(&r.CustomerCreditBalancePolicy))
	case 17:
		return (*string)(unsafe.Pointer(&r.OverCreditPolicy))
	case 18:
		return (*string)(unsafe.Pointer(&r.SupersededInvoiceVisibilityPolicy))
	case 19:
		return &r.Version
	case 20:
		return &r.CreatedAt
	case 21:
		return &r.UpdatedAt
	}
	return nil
}

func valueInvoiceAdjustmentControl(p unsafe.Pointer, c int32) any {
	r := (*invoiceadjustmentcontrol.InvoiceAdjustmentControl)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.PartiallyPaidInvoiceAdjustmentPolicy)
	case 4:
		return string(r.PaidInvoiceAdjustmentPolicy)
	case 5:
		return string(r.DisputedInvoiceAdjustmentPolicy)
	case 6:
		return string(r.AdjustmentAccountingDatePolicy)
	case 7:
		return string(r.ClosedPeriodAdjustmentPolicy)
	case 8:
		return string(r.AdjustmentReasonRequirement)
	case 9:
		return string(r.StandardAdjustmentApprovalPolicy)
	case 10:
		if r.StandardAdjustmentApprovalThreshold.IsZero() {
			return nil
		}
		return r.StandardAdjustmentApprovalThreshold
	case 11:
		return string(r.WriteOffApprovalPolicy)
	case 12:
		if r.WriteOffApprovalThreshold.IsZero() {
			return nil
		}
		return r.WriteOffApprovalThreshold
	case 13:
		return r.RequireSeparateApprover
	case 14:
		return r.RerateVarianceTolerancePercent
	case 15:
		return string(r.ReplacementInvoiceReviewPolicy)
	case 16:
		return string(r.CustomerCreditBalancePolicy)
	case 17:
		return string(r.OverCreditPolicy)
	case 18:
		return string(r.SupersededInvoiceVisibilityPolicy)
	case 19:
		return r.Version
	case 20:
		return r.CreatedAt
	case 21:
		return r.UpdatedAt
	}
	return nil
}

